from review import card,save,DATE
i='TCS-3691';_,c=card(i);refs=c['references'];refs[0]['locator']='Definitions 3–4 for total-variation influence and row-sum coefficient; Theorem 10 for learning; Section 5 opening question and Theorem 16 for the stronger log-influence hypothesis.'
refs += [dict(id='full',title='Learning from Weakly Dependent Data under Dobrushin’s Condition',authors='Yuval Dagan; Constantinos Daskalakis; Nishanth Dikkala; Siddhartha Jayanti',year=2019,url='https://arxiv.org/abs/1906.09247',pdf_url='https://arxiv.org/pdf/1906.09247',locator='Full version, 21 June 2019; Definitions 2.1–2.2, Theorem 4.5 and Corollary 4.6; Section 5, Theorem 5.3 and equation (18), the explicit iid-order finite-VC sample-complexity target.')]
notes=['Recovered total-variation conditional influence, the incoming row sum and a fixed slack below one.','Interpreted the source’s “such bounds” as the iid-order finite-VC uniform-convergence rate displayed in full-version equation (18); this quantitative interpretation is explicit and is not claimed equivalent to mere qualitative convergence.','Defined common marginals, zero-one population/empirical risk, VC dimension, quantifier order, conditional-kernel versions and measurability conventions.','Separated finite-VC learnability already proved under ordinary Dobrushin dependence from simultaneous uniform convergence, which is proved under a stronger logarithmic influence condition.','Read both conference and full versions and searched subsequent empirical-process and dependent-learning work; no settlement of this precise extension was located.']
save(i,dict(formal='For every a∈[0,1), does there exist a finite constant C_a such that the following holds uniformly? Let m≥1, let H be a nonempty class of measurable binary functions on a measurable instance space X with finite VC dimension d, and let P_m be a joint law of S=(Z₁,…,Z_m), Z_i=(X_i,Y_i)∈X×{0,1}, whose marginals all equal D and whose total-variation Dobrushin coefficient is at most a. For every δ∈(0,1), require Pr_{S∼P_m}[sup_{h∈H}|L_S(h)−L_D(h)|>C_a√((d+log(2/δ))/m)]≤δ. Here L_S and L_D are zero-one losses and the conditional-kernel and measurability conventions below are part of the model. This card reads the source’s proposed extension quantitatively, using the iid-order finite-VC rate stated in equation (18) of its full version; it is not merely a claim that some unspecified convergence rate exists.',definitions='Write Z=X×{0,1}. For each i, take a probability kernel κ_i(·|z_{−i}) that is a version of the conditional law of Z_i given all other coordinates under P_m. These kernels are defined on the entire product Z^{m−1}, including configurations of zero marginal probability. For i≠j define c_{ij}=sup{TV(κ_i(·|u),κ_i(·|v)):u,v∈Z^{m−1}, u and v agree except possibly in coordinate j}, where TV(μ,ν)=sup_{B measurable}|μ(B)−ν(B)|. In a finite space this is one half of the sum of absolute probability differences. The admissibility promise is existence of such conditional-kernel versions with max_i Σ_{j≠i}c_{ij}≤a. Thus the influence of coordinate j on coordinate i is bounded, and the sum is over influences entering i; it is not a column-sum or a Markov-chain mixing-time condition. Specifying versions on null configurations prevents undefined conditioning from deciding the promise. Kernels satisfying this global bound and a measurable random supremum in the displayed event are assumed; these are the explicit regularity conventions for the source’s conditional-distribution notation. No independence, graph degree, spatial dimension, stationarity or exchangeability beyond identical marginals is assumed. For h:X→{0,1}, L_S(h)=m⁻¹Σ_i 1{h(X_i)≠Y_i}, and L_D(h)=E_{(X,Y)∼D}1{h(X)≠Y}. A finite F⊆X is shattered if every binary labeling of F is the restriction of a member of H. VC(H) is the largest size of a shattered set, or infinity if these sizes are unbounded. The hypothesis d<∞ includes d=0. The constant C_a may depend on the fixed upper bound a and may diverge as a approaches one, but must be independent of m,d,δ,X,H,D and P_m. The law P_m may be different for each m; no consistency of an infinite process is required. The logarithm is natural. This is a statistical inequality, with no algorithmic running-time requirement.',question_type='yes_no',answer_criterion='Prove existence of such a constant for every fixed a<1, uniformly over all the displayed models and parameters, or refute this quantified rate. A negative answer must defeat every proposed constant for some fixed a<1; a family with its coefficient tending to one does not by itself suffice. Proving generalization only for a particular learner, a bound depending on the cardinality of H, a slower rate, or a result needing stronger log-influence assumptions does not establish the displayed extension.',context_blocks=[dict(title='Ordinary weak dependence already permits learning',text='The paper proves learnability for finite-VC classes under the ordinary total-variation Dobrushin condition. A guarantee for the hypothesis returned by that learner does not assert that every hypothesis has an accurate empirical loss.',citation='full'),dict(title='Uniform convergence is known under a stronger condition',text='Theorem 5.3 assumes α_log<1/2, where α_log sums worst-case logarithmic probability-ratio influences. Ordinary total-variation influences are no larger, so this is a stronger restriction. The resulting finite-VC sample complexity is O((d+log(1/δ))/ε²) at fixed slack, as stated in equation (18).',citation='full'),dict(title='The target is the finite-VC consequence',text='The source separately gives a Gaussian-complexity theorem for much more general real-valued losses. This card retains its explicit finite-VC classification question and asks for the same rate with ordinary Dobrushin dependence. It does not demand the full real-valued empirical-process theorem.',citation='primary'),dict(title='Fixed slack is essential to the quantifiers',text='The question allows its constant to depend on a<1. It asks whether the usual sample-size dependence survives throughout that regime, without specifying an optimal blow-up as a approaches the boundary.',citation='full')],why='Would determine whether the standard weak-influence condition suffices for the uniform statistical guarantees that make finite VC dimension useful, beyond the already-known existence of a successful learner.',references=refs,progress=[dict(date='2019',text='The conference paper proves learning under total-variation Dobrushin dependence and uniform convergence under the stronger log-influence condition, leaving the finite-VC extension open.',citation='primary'),dict(date='2019-06-21',text='The full version retains the question and explicitly displays the iid-order finite-VC sample complexity following Theorem 5.3.',citation='full')],status='open',status_note='Read the source definitions, its learning theorem and the stronger uniform-convergence theorem in the conference and full versions. Searches through 12 September 2026 did not locate a proof or refutation of the displayed ordinary-Dobrushin finite-VC rate. The 2026 product-space uniform-law paper concerns another estimator and distributional structure, not this empirical-mean extension. The lack of a located resolution is not an exhaustive current-status guarantee.',model_self_contained=True,requires_context=False,review_note='Explicit quantitative interpretation based on equation (18); preserves the distinction between ordinary and logarithmic influence and between learnability and uniform convergence.',importance=dict(score=c['importance']['score'],method='editorial',reason='A structural boundary for transferring VC uniform-convergence guarantees from independent samples to dependent data, with implications for empirical-risk validation. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A dependent training sample has identical marginal distributions and a bounded total influence on every coordinate.','Uniform convergence requires every hypothesis’s empirical zero-one loss to approximate its population loss.','The card asks whether every finite-VC class has the usual square-root rate when the ordinary Dobrushin coefficient stays below one.','The source already proves learnability under that condition, but its uniform-convergence theorem requires stronger logarithmic influences.','The formulation makes the iid-order rate and fixed dependence slack explicit, without claiming an optimal constant near the boundary.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full'])),notes=notes,checked_sources=[r['url'] for r in refs]+['https://proceedings.mlr.press/v336/holzman26a.html'])
